/* The contract between the recompiled game code (generated by recomp/recomp.py) and the runtime.
 *
 * Every game function becomes `void f_<module>_<address>(Ctx *c)` operating on the CPU state in Ctx. Memory is one
 * host allocation standing in for the PSP's address space, indexed by the PSP address with the cached / uncached /
 * kernel mirror bits masked off. Anything the generated code cannot do inline is a call into the runtime: calls by
 * address (into overlay regions, through pointers), the imported system functions, the VFPU, and the odd instruction
 * with awkward semantics. */
#ifndef RECOMP_H
#define RECOMP_H

#include <stdint.h>
#include <string.h>

typedef struct Ctx {
    uint32_t r[32];                 /* GPRs; r[0] stays 0 (the generated code never writes it) */
    uint32_t hi, lo;
    union { float f; uint32_t u; int32_t i; } f[32];   /* FPU registers */
    uint32_t fcr31;
    int fpcond;                     /* FPU condition (fcr31 bit 23, kept apart for speed) */
    float v[128];                   /* VFPU registers */
    uint32_t vfpu_ctrl[16];         /* VFPU control: prefixes (0-2), condition codes (3), ... */
    uint8_t *mem;                   /* the PSP address space */
} Ctx;

#define VFPU_CTRL_CC 3

/* Memory: the PSP's address bits 30-31 select mirrors (kernel, uncached) of the same memory. */
#define ADDR_MASK 0x3FFFFFFFu
#define MEM(a) (c->mem + ((uint32_t)(a) & ADDR_MASK))
#define LB(a)  (*(int8_t *)MEM(a))
#define LBU(a) (*(uint8_t *)MEM(a))
#define LH(a)  (*(int16_t *)MEM(a))
#define LHU(a) (*(uint16_t *)MEM(a))
#define LW(a)  (*(uint32_t *)MEM(a))
#define SB(a, v) (*(uint8_t *)MEM(a) = (uint8_t)(v))
#define SH(a, v) (*(uint16_t *)MEM(a) = (uint16_t)(v))
#define SW(a, v) (*(uint32_t *)MEM(a) = (uint32_t)(v))

typedef void (*RecompFunc)(Ctx *c);

/* Calls the runtime resolves: by address (into an overlay region - dispatched on the overlay resident there - or
 * through a pointer), and to an import stub (by its address in the EBOOT's stub table). */
void rt_call(Ctx *c, uint32_t addr);
void hle_call(Ctx *c, uint32_t stub);

/* A jump table index with no case, a `break`, code nothing should reach. */
void rt_bad_jump(Ctx *c, uint32_t value, uint32_t at);
void rt_break(Ctx *c, uint32_t at);
void rt_unreachable(Ctx *c, uint32_t at);

/* The native frame rate (recomp/patches.py): 30 / the game's frames a second (MHFU_TICK_HZ), 1 at its own rate; and
 * whether this game frame is one where a frame at 30 a second falls (always, at the game's own rate) */
extern float rt_time_scale;
extern int rt_tick30;
extern int rt_ticks60;          /* the 60ths of a second this game frame takes up (2 at 30 a second; 2 within gated code) */
extern int rt_frame30;          /* this game frame is one a 30th falls on (rt_tick30 is 1 within gated code) */
void rt_frame_start(void);      /* the main loop's top, each game frame */
int rt_next_frame30(void);      /* the next game frame is one a 30th falls on */
/* gated code (fn, or a call to addr; at: the call, or the function gated): as at 30 a second */
void rt_gate(Ctx *c, void (*fn)(Ctx *c), uint32_t addr, uint32_t at);
void rt_list_link(uint32_t mgr, uint32_t start, uint32_t count, uint32_t layer);  /* a display list chunk linked */
void rt_hud_part(int part);        /* the hunt's HUD's part being drawn: 1 gauges, 2 map, 3 item bar, 0 none (gpu.c) */
void rt_hud_text_queued(uint32_t entry);  /* a text's entry added (noted with the part) */
void rt_hud_text_drawn(uint32_t entry);   /* a text's entry being drawn (its part, as noted) */
void rt_gate_before(Ctx *c, void (*fn)(Ctx *c), uint32_t addr, uint32_t at);    /* on the frames before a 30th */
void rt_gate_object(Ctx *c, void (*fn)(Ctx *c), uint32_t addr, uint32_t at);    /* an object's tick (a0) */
void rt_gate_native(Ctx *c, void (*fn)(Ctx *c), uint32_t addr, uint32_t at);    /* converted, under a gate */
void rt_trace_call(Ctx *c, uint32_t fn);   /* a call of fn (recomp.py's RECOMP_TRACE): logged with MHFU_CALL_LOG */
extern int rt_camera_free;      /* the mouse has the camera: the game's own turns of it (away from walls) are off */
extern float rt_cull_margin;    /* models within this of the camera's view are drawn too (for the renderer's shadows) */
int rt_view_test(Ctx *c);       /* (shadow_extras.c: those drawn, apart from the game) */
void rt_queues_cleared(void);
void rt_render_pass_begin(void);
void rt_shadow_extras(Ctx *c);
extern int rt_shadow_extras_running;    /* (what the render pass draws besides the queues is left out of a pass apart) */
void rt_menu_list(uint32_t layout, uint32_t row);   /* a list window drawn, its cursor's bar on row (menu.c) */
void rt_menu_bar(uint32_t x, uint32_t y, uint32_t w, uint32_t h);   /* a menu cursor's bar drawn (menu.c) */
void rt_menu_item(uint32_t x, uint32_t y, uint32_t w, uint32_t h, int selected, uint32_t cursor);  /* a list's item drawn
                                                                                                (menu.c) */
void rt_menu_sound(Ctx *c);     /* the cursor's sound, for a cursor the mouse moved (menu.c) */
void rt_menu_grid(int x, int y, int pitch_x, int pitch_y, int w, int h, int cols, int n, uint32_t cursor,
                  int sound);    /* a grid of slots drawn, its cursor a byte (menu.c) */
int rt_sprite(Ctx *c, uint32_t sprite, uint32_t x, uint32_t y, int w, int h);  /* a HUD sprite drawn (w < 0: its own
                                                                   size): 1 if a PSP button's, a key shown instead (glyphs.c) */
void rt_menu_cursor(uint32_t cursor, uint32_t rows, uint32_t *buttons);  /* a menu's cursor moved (menu.c) */
void rt_menu_arrows(uint32_t x, uint32_t y, uint32_t w);    /* a left and right arrow drawn (menu.c) */

/* Instructions done by the runtime */
void vfpu_exec(Ctx *c, uint32_t instr, uint32_t at);    /* any VFPU instruction but a branch */
uint32_t rt_lwl(Ctx *c, uint32_t addr, uint32_t old);
uint32_t rt_lwr(Ctx *c, uint32_t addr, uint32_t old);
void rt_swl(Ctx *c, uint32_t addr, uint32_t v);
void rt_swr(Ctx *c, uint32_t addr, uint32_t v);
uint32_t rt_cfc1(Ctx *c, int reg);
void rt_ctc1(Ctx *c, int reg, uint32_t v);

static inline void rt_div(Ctx *c, int32_t a, int32_t b) {
    if (b == 0) {                               /* as the Allegrex does (PPSSPP's MIPSInt) */
        c->hi = (uint32_t)a;
        c->lo = a < 0 ? 1 : 0xFFFFFFFFu;
    } else if (a == (int32_t)0x80000000 && b == -1) {
        c->hi = 0;
        c->lo = 0x80000000u;
    } else {
        c->lo = (uint32_t)(a / b);
        c->hi = (uint32_t)(a % b);
    }
}

static inline void rt_divu(Ctx *c, uint32_t a, uint32_t b) {
    if (b == 0) {
        c->hi = a;
        c->lo = a <= 0xFFFF ? 0xFFFF : 0xFFFFFFFFu;
    } else {
        c->lo = a / b;
        c->hi = a % b;
    }
}

static inline uint32_t rt_trunc_w(float f) {    /* trunc.w.s; out of range or NaN gives 0x7FFFFFFF */
    if (!(f >= -2147483648.0f && f < 2147483648.0f))
        return f < 0 ? 0x80000000u : 0x7FFFFFFFu;
    return (uint32_t)(int32_t)f;
}

static inline uint32_t rt_bitrev(uint32_t v) {
    v = ((v >> 1) & 0x55555555u) | ((v & 0x55555555u) << 1);
    v = ((v >> 2) & 0x33333333u) | ((v & 0x33333333u) << 2);
    v = ((v >> 4) & 0x0F0F0F0Fu) | ((v & 0x0F0F0F0Fu) << 4);
    v = ((v >> 8) & 0x00FF00FFu) | ((v & 0x00FF00FFu) << 8);
    return (v >> 16) | (v << 16);
}

static inline uint32_t rt_clz(uint32_t v) { return v ? (uint32_t)__builtin_clz(v) : 32; }
static inline uint32_t rt_rotr(uint32_t v, unsigned s) { s &= 31; return s ? (v >> s) | (v << (32 - s)) : v; }

/* The generated tables: every module and its functions, for dispatch by address */
typedef struct { uint32_t addr; RecompFunc func; } RecompEntry;
typedef struct {
    const char *name;
    int region;                     /* 0 the EBOOT, 1 tasks, 2 subs, 3 monsters, 4 stages */
    int number;                     /* the overlay number in its header (0 for the EBOOT) */
    uint32_t base;
    const RecompEntry *funcs;       /* sorted by address */
    int nfuncs;
} RecompModule;

extern const RecompModule recomp_modules[];
extern const int recomp_nmodules;

typedef struct { uint32_t stub; const char *library; uint32_t nid; } RecompImport;
extern const RecompImport recomp_imports[];
extern const int recomp_nimports;

#endif
